class SaslAuthCommand {
public:
    SaslAuthCommand(Module* creator, SimpleExtItem<SaslAuthenticator>& ext, GenericCap& cap) {
        // Initialize the command with specific parameters
        SetName("SASL AUTHENTICATE");
        SetDescription("Authenticates a user using SASL");
        SetUsageSyntax("<mechanism>");
        SetMinParameters(1);
        AccessClawback(true);
        SetFlag(CLF_UNREGISTERED);
        SetFlag(CLF_SILENT);
    }

    CmdResult Handle(User* user, const CmdDataList& parameters) {
        if (user->IsRegistered()) {
            return CMD_FAILURE;
        }

        if (parameters.size() != 1) {
            return CMD_FAILURE;
        }

        std::string mechanism = parameters[0].param;

        // Check if the mechanism is supported
        if (mechanism != "PLAIN" && mechanism != "DIGEST-MD5") {
            return CMD_FAILURE;
        }

        SaslAuthenticator* authenticator = new SaslAuthenticator(user, mechanism);
        if (!authenticator->Start()) {
            delete authenticator;
            return CMD_FAILURE;
        }

        user->SetExt<SaslAuthenticator>(ext, authenticator);
        user->SetCap(GenericCap::SASL);

        return CMD_SUCCESS;
    }
};

class SaslAuthCommand {
public:
    SaslAuthCommand(Module* Creator, SimpleExtItem<SaslAuthenticator>& ext, GenericCap& Cap) {
        this->Creator = Creator;
        this->ext = &ext;
        this->Cap = &Cap;
    }

    int Handle(User* user, std::vector<std::string>& parameters) {
        if (user->registered) {
            return CMD_FAILURE;
        }

        if (parameters.size() < 1) {
            return CMD_FAILURE;
        }

        SaslAuthenticator* authenticator = ext->Get(user);
        if (!authenticator) {
            authenticator = new SaslAuthenticator();
            ext->Set(user, authenticator);
        }

        std::string method = parameters[0];
        if (method == "PLAIN") {
            if (parameters.size() < 2) {
                return CMD_FAILURE;
            }

            std::string data = parameters[1];
            if (authenticator->StartPLAIN(data)) {
                Cap->Add(user, "sasl");
                return CMD_SUCCESS;
            }
        }

        return CMD_FAILURE;
    }

private:
    Module* Creator;
    SimpleExtItem<SaslAuthenticator>* ext;
    GenericCap* Cap;
};

