class SaslAuthCommand {
public:
    SaslAuthCommand(Module* creator, SimpleExtItem<SaslAuthenticator>& ext, GenericCap& cap)
        : creator(creator), ext(ext), cap(cap) {
        // Initialize the command with specific parameters and set properties related to its execution
    }

    CmdResult Handle(User* user, const CmdData& data) {
        if (user->registered) {
            return CMD_FAILURE;
        }

        if (data.params.size() != 1) {
            return CMD_FAILURE;
        }

        const std::string& mechanism = data.params[0];
        SaslAuthenticator* authenticator = ext.get(user);

        if (authenticator && authenticator->isAuthenticated()) {
            return CMD_FAILURE;
        }

        if (!authenticator) {
            authenticator = new SaslAuthenticator();
            ext.set(user, authenticator);
        }

        if (!authenticator->start(mechanism)) {
            return CMD_FAILURE;
        }

        return CMD_SUCCESS;
    }

private:
    Module* creator;
    SimpleExtItem<SaslAuthenticator>& ext;
    GenericCap& cap;
};
